using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerResourceType]
public static class ConfigResources
{
    private static readonly Dictionary<string, object> AppConfig = new()
    {
        ["environment"] = "production",
        ["maxRetries"] = 3,
        ["featureFlags"] = new Dictionary<string, bool>
        {
            ["darkMode"] = true,
            ["betaFeatures"] = false
        }
    };

    [McpServerResource(
        UriTemplate = "config://app",
        Name = "App Configuration",
        MimeType = "application/json"),
     Description("Returns the current application configuration as JSON.")]
    public static string GetAppConfig() =>
        JsonSerializer.Serialize(AppConfig, new JsonSerializerOptions { WriteIndented = true });

    [McpServerResource(
        UriTemplate = "config://app/environment",
        Name = "Environment Name",
        MimeType = "text/plain"),
     Description("Returns the current deployment environment name.")]
    public static string GetEnvironment() =>
        AppConfig["environment"].ToString()!;
}

using System.ComponentModel;
using ModelContextProtocol.Server;

[McpServerToolType]
public static class EchoTools
{
    [McpServerTool, Description("Echoes the input message back, optionally in uppercase.")]
    public static string Echo(
        [Description("The message to echo back")] string message,
        [Description("If true, converts the message to uppercase")] bool uppercase = false) =>
        uppercase ? message.ToUpperInvariant() : message;

    [McpServerTool, Description("Returns the current server UTC time.")]
    public static string GetServerTime() =>
        DateTime.UtcNow.ToString("o");
}

